export function groupAdminCapabilities(overview) {
  const groups = emptyAdminCapabilityGroups();
  for (const capability of overview?.capabilities ?? []) {
    groups[groupKeyForAdminStatus(capability.status)].push(capability);
  }
  return groups;
}

export function adminCapabilityView(capability) {
  const actionKind = adminCapabilityActionKind(capability);
  const isBrowserRunnable = actionKind === 'browser_action' && capability.canStartFromBrowser !== false;
  const isWorkerEntrypoint = actionKind === 'worker_entrypoint';
  const isCliOnly = actionKind === 'cli_command';
  const isRunbookOnly = actionKind === 'runbook_step';
  const isFuture = actionKind === 'future';
  return {
    capability,
    status: capability.status,
    badge: adminCapabilityBadge(capability.status),
    primarySurface: capability.sdkSurface ?? capability.command ?? capability.apiRoute,
    actionKind,
    canRenderActionButton: isBrowserRunnable,
    isBrowserRunnable,
    isWorkerEntrypoint,
    isCliOnly,
    isRunbookOnly,
    isFuture,
    executionSurface: capability.executionSurface,
    requiresApproval: capability.requiresApproval,
    operatorChecklist: capability.operatorChecklist ?? [],
    blockingReason: capability.blockingReason ?? null,
    disabledReason: isBrowserRunnable
      ? null
      : (capability.blockingReason ?? adminCapabilityDisabledReason(capability)),
  };
}

export function adminReadinessScreen(overview) {
  const capabilityGroups = groupAdminCapabilities(overview);
  const capabilityViews = (overview?.capabilities ?? []).map(adminCapabilityView);
  const browserRunnableCapabilityViews = capabilityViews.filter(
    (capability) => capability.isBrowserRunnable,
  );
  return {
    overview: overview ?? null,
    capabilityGroups,
    capabilityViews,
    browserRunnableCapabilityViews,
    blockedCapabilityViews: capabilityViews.filter((capability) => !capability.isBrowserRunnable),
    workerEntrypointCapabilityViews: capabilityViews.filter((capability) => capability.isWorkerEntrypoint),
    cliOnlyCapabilityViews: capabilityViews.filter((capability) => capability.isCliOnly),
    runbookOnlyCapabilityViews: capabilityViews.filter((capability) => capability.isRunbookOnly),
    futureCapabilityViews: capabilityViews.filter((capability) => capability.isFuture),
    canPublishOutbox: capabilityGroups.apiAvailable.some(
      (capability) => capability.id === 'bounded-outbox-publish',
    ),
    hasCliOnlyWork: capabilityGroups.cliOnly.length > 0,
    hasWorkerEntrypoints: capabilityGroups.workerEntrypoints.length > 0,
    hasRunbookOnlyWork: capabilityGroups.runbookOnly.length > 0,
    hasFutureWork: capabilityGroups.future.length > 0,
  };
}

export function adminTaskView(task) {
  const canRenderActionButton = task.canStartFromBrowser === true;
  const canShowCommand = task.executionSurface === 'worker_entrypoint' ||
    task.executionSurface === 'cli' ||
    task.executionSurface === 'runbook';
  const requiresBackendSurface = Boolean(task.requiredBackendSurface);
  return {
    task,
    area: task.area,
    badge: adminTaskBadge(task),
    primarySurface: task.primarySurface,
    canRenderActionButton,
    canShowCommand,
    requiresOperatorApproval: task.requiresApproval,
    requiresBackendSurface,
    disabledReason: canRenderActionButton ? null : adminTaskDisabledReason(task),
    checklist: task.operatorChecklist ?? [],
  };
}

export function adminTaskPlanScreen(plan) {
  const taskViews = (plan?.tasks ?? []).map(adminTaskView);
  const browserRunnableTaskViews = taskViews.filter((view) => view.canRenderActionButton);
  const operatorRequiredTaskViews = taskViews.filter((view) => view.requiresOperatorApproval);
  const futureBackendSurfaceTaskViews = taskViews.filter((view) => view.requiresBackendSurface);
  return {
    plan: plan ?? null,
    taskViews,
    browserRunnableTaskViews,
    operatorRequiredTaskViews,
    futureBackendSurfaceTaskViews,
    workerTaskViews: taskViews.filter((view) => view.area === 'worker'),
    migrationTaskViews: taskViews.filter((view) => view.area === 'migration'),
    bootstrapTaskViews: taskViews.filter((view) => view.area === 'bootstrap'),
    hasBrowserRunnableTasks: browserRunnableTaskViews.length > 0,
    hasOperatorRequiredTasks: operatorRequiredTaskViews.length > 0,
    hasFutureBackendSurfaces: futureBackendSurfaceTaskViews.length > 0,
  };
}

export function adminOperationsBoard(overview, plan) {
  const readiness = adminReadinessScreen(overview);
  const taskPlan = adminTaskPlanScreen(plan);
  const operatorCommandTaskViews = taskPlan.taskViews.filter((view) => view.canShowCommand);
  const futureTaskViews = taskPlan.taskViews.filter(
    (view) => view.task.status === 'future' || view.area === 'workspace',
  );
  return {
    overview: overview ?? null,
    plan: plan ?? null,
    readiness,
    taskPlan,
    browserRunnableTaskViews: taskPlan.browserRunnableTaskViews,
    operatorCommandTaskViews,
    migrationTaskViews: taskPlan.migrationTaskViews,
    workerTaskViews: taskPlan.workerTaskViews,
    bootstrapTaskViews: taskPlan.bootstrapTaskViews,
    futureTaskViews,
    commandRows: operatorCommandTaskViews
      .filter((view) => Boolean(view.task.command))
      .map((view) => ({
        task: view.task,
        view,
        command: view.task.command,
        evidencePath: view.task.evidencePath ?? null,
        disabledReason: view.disabledReason,
      })),
    evidenceTaskViews: taskPlan.taskViews.filter((view) => Boolean(view.task.evidencePath)),
    requiredBackendSurfaces: groupAdminRequiredBackendSurfaces(
      taskPlan.futureBackendSurfaceTaskViews,
    ),
    hasBrowserRunnableTasks: taskPlan.hasBrowserRunnableTasks,
    hasOperatorCommands: operatorCommandTaskViews.length > 0,
    hasRequiredBackendSurfaces: taskPlan.hasFutureBackendSurfaces,
  };
}

function groupAdminRequiredBackendSurfaces(taskViews) {
  const grouped = new Map();
  for (const view of taskViews) {
    const surface = view.task.requiredBackendSurface;
    if (!surface) continue;
    const views = grouped.get(surface) ?? [];
    views.push(view);
    grouped.set(surface, views);
  }
  return Array.from(grouped.entries()).map(([surface, taskViews]) => ({
    surface,
    taskViews,
    taskCount: taskViews.length,
  }));
}

function adminTaskBadge(task) {
  switch (task.executionSurface) {
    case 'browser_sdk':
      return 'Browser SDK';
    case 'worker_entrypoint':
      return 'Worker command';
    case 'cli':
      return 'CLI command';
    case 'runbook':
      return 'Runbook';
    case 'future':
      return 'Future surface';
  }
}

function adminTaskDisabledReason(task) {
  if (task.blockingReason) return task.blockingReason;
  if (task.requiredBackendSurface) return `Requires ${task.requiredBackendSurface}.`;
  return 'This admin task cannot be started from the browser.';
}

function adminCapabilityActionKind(capability) {
  switch (capability.status) {
    case 'api_available':
      return capability.sdkSurface ? 'browser_action' : 'api_without_sdk';
    case 'worker_entrypoint':
      return 'worker_entrypoint';
    case 'cli_only':
      return 'cli_command';
    case 'runbook_only':
      return 'runbook_step';
    case 'future':
      return 'future';
  }
}

function adminCapabilityBadge(status) {
  switch (status) {
    case 'api_available':
      return 'API available';
    case 'worker_entrypoint':
      return 'Worker entrypoint';
    case 'cli_only':
      return 'CLI only';
    case 'runbook_only':
      return 'Runbook only';
    case 'future':
      return 'Future';
  }
}

function adminCapabilityDisabledReason(capability) {
  switch (capability.status) {
    case 'worker_entrypoint':
      return 'This capability has a worker entrypoint but no browser-safe control surface yet.';
    case 'cli_only':
      return 'This capability is CLI-only and should not be rendered as a browser action button.';
    case 'runbook_only':
      return 'This capability is documented as a runbook step, not a browser action.';
    case 'future':
      return capability.nextSurface ?? 'This capability is future work and is not currently executable.';
    case 'api_available':
      return capability.sdkSurface ? '' : 'This API-backed capability has no generated SDK surface yet.';
  }
}

function emptyAdminCapabilityGroups() {
  return {
    apiAvailable: [],
    workerEntrypoints: [],
    cliOnly: [],
    runbookOnly: [],
    future: [],
  };
}

function groupKeyForAdminStatus(status) {
  switch (status) {
    case 'api_available':
      return 'apiAvailable';
    case 'worker_entrypoint':
      return 'workerEntrypoints';
    case 'cli_only':
      return 'cliOnly';
    case 'runbook_only':
      return 'runbookOnly';
    case 'future':
      return 'future';
  }
}

function mediaUploadFormData(payload) {
  const form = new FormData();
  const suppliedMimeType = payload.suppliedMimeType ?? payload.file?.type ?? 'application/octet-stream';
  const filePart = payload.file instanceof Blob ? payload.file : new Blob([payload.file], {
    type: suppliedMimeType,
  });
  form.append('logicalPath', payload.logicalPath);
  form.append('schemaType', payload.schemaType);
  form.append('format', payload.format);
  form.append('suppliedMimeType', suppliedMimeType);
  form.append('securityEnvelope', JSON.stringify(payload.securityEnvelope ?? {}));
  if (payload.probeMetadata !== undefined && payload.probeMetadata !== null) {
    form.append('probeMetadata', JSON.stringify(payload.probeMetadata));
  }
  const filename = payload.fileName ?? payload.logicalPath.split('/').pop() ?? 'upload.bin';
  form.append('file', filePart, filename);
  return form;
}

function sourceFilePart(file, suppliedMimeType) {
  return file instanceof Blob ? file : new Blob([file], { type: suppliedMimeType });
}

function sourceCsvUploadFormData(payload) {
  const form = new FormData();
  const suppliedMimeType = payload.file?.type ?? 'text/csv';
  const filePart = sourceFilePart(payload.file, suppliedMimeType);
  form.append('sourceName', payload.sourceName);
  form.append('displayName', payload.displayName);
  form.append('datasetRef', payload.datasetRef);
  if (payload.syncName !== undefined && payload.syncName !== null) form.append('syncName', payload.syncName);
  form.append('primaryKey', JSON.stringify(payload.primaryKey ?? []));
  form.append('file', filePart, payload.fileName ?? 'upload.csv');
  return form;
}

function sourceBatchFileUploadFormData(payload) {
  const form = new FormData();
  const manifest = {
    sourceName: payload.sourceName,
    displayName: payload.displayName,
    syncName: payload.syncName ?? null,
    files: payload.files.map((item) => ({ fileName: item.fileName, datasetRef: item.datasetRef })),
  };
  form.append('manifest', JSON.stringify(manifest));
  for (const item of payload.files) {
    const suppliedMimeType = item.file?.type ?? 'text/csv';
    form.append('files', sourceFilePart(item.file, suppliedMimeType), item.fileName);
  }
  return form;
}

function sourceMediaUploadFormData(payload) {
  const form = mediaUploadFormData(payload);
  form.append('sourceName', payload.sourceName);
  form.append('displayName', payload.displayName);
  form.append('mediaSetId', payload.mediaSetId);
  return form;
}

